from fastapi import APIRouter, Depends, Query, status
from sqlalchemy.ext.asyncio import AsyncSession

from app.auth.deps import require_manager
from app.auth.models import User
from app.db import get_db
from app.violations.schemas import PushSubscriptionCreate, PushSubscriptionOut, ZoneViolationOut
from app.violations.service import list_push_subscriptions, list_violations, register_push_subscription

violations_router = APIRouter(prefix="/api/v1/violations", tags=["violations"])


@violations_router.get("", response_model=list[ZoneViolationOut])
async def list_violations_endpoint(
    limit: int = Query(50, ge=1, le=200),
    offset: int = Query(0, ge=0),
    current_user: User = Depends(require_manager),
    db: AsyncSession = Depends(get_db),
) -> list[ZoneViolationOut]:
    return await list_violations(db, limit=limit, offset=offset)


push_subscriptions_router = APIRouter(prefix="/api/v1/push-subscriptions", tags=["push-subscriptions"])


@push_subscriptions_router.post("", response_model=PushSubscriptionOut, status_code=status.HTTP_201_CREATED)
async def register_push_subscription_endpoint(
    body: PushSubscriptionCreate,
    current_user: User = Depends(require_manager),
    db: AsyncSession = Depends(get_db),
) -> PushSubscriptionOut:
    return await register_push_subscription(
        db, tenant_id=current_user.tenant_id, manager_id=current_user.id,
        endpoint=body.endpoint, p256dh=body.p256dh, auth=body.auth,
    )


@push_subscriptions_router.get("", response_model=list[PushSubscriptionOut])
async def list_push_subscriptions_endpoint(
    current_user: User = Depends(require_manager),
    db: AsyncSession = Depends(get_db),
) -> list[PushSubscriptionOut]:
    return await list_push_subscriptions(db, manager_id=current_user.id)
